#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
static const tree*find(const tree*r,const char*l){if(!strcmp(r->label,l))return r;for(size_t i=0;i<r->count;i++){const tree*t=find(r->children[i],l);if(t)return t;}return NULL;}static const tree*parent(const tree*r,const tree*t){for(size_t i=0;i<r->count;i++){if(r->children[i]==t)return r;const tree*p=parent(r->children[i],t);if(p)return p;}return NULL;}static tree*clone(const tree*root,const tree*r,const tree*previous){tree*t=(tree*)calloc(1,sizeof(tree));t->label=r->label;const tree*p=parent(root,r);for(size_t i=0;i<=r->count;i++){const tree*c=i==r->count?p:r->children[i];if(!c||c==previous)continue;t->children=(tree**)realloc(t->children,(t->count+1)*sizeof(tree*));t->children[t->count++]=clone(root,c,r);}return t;}tree*from_pov(const tree*r,const char*l){if(!r)return NULL;const tree*t=find(r,l);return t?clone(r,t,NULL):NULL;}static bool path(const tree*root,const tree*r,const tree*previous,const char*to,const char**out,size_t*count){out[(*count)++]=r->label;if(!strcmp(r->label,to))return true;const tree*p=parent(root,r);for(size_t i=0;i<=r->count;i++){const tree*c=i==r->count?p:r->children[i];if(c&&c!=previous&&path(root,c,r,to,out,count))return true;}--*count;return false;}size_t path_to(const tree*r,const char*from,const char*to,const char**out){if(!r)return 0;const tree*t=find(r,from);if(!t||!find(r,to))return 0;size_t n=0;path(r,t,NULL,to,out,&n);return n;}void tree_free(tree*r){if(!r)return;for(size_t i=0;i<r->count;i++)tree_free(r->children[i]);free(r->children);free(r);}

