static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
tree a={"a",NULL,0},b={"b",NULL,0},c={"c",NULL,0};tree*bc[]={&c};b.children=bc;b.count=1;tree*ab[]={&a,&b};tree r={"r",ab,2};const char*o[10];assert(path_to(&r,"a","c",o)==4&&!strcmp(o[0],"a")&&!strcmp(o[1],"r")&&!strcmp(o[3],"c"));assert(path_to(&r,"x","c",o)==0);tree*t=from_pov(&r,"c");assert(t&&!strcmp(t->label,"c")&&!strcmp(t->children[0]->label,"b")&&!strcmp(t->children[0]->children[0]->label,"r"));tree_free(t);assert(!from_pov(&r,"x"));

return 0;}
